```go
package main

import (
	"encoding/json"
	"fmt"
	"go/ast"
	"go/format"
	"io/ioutil"
	"log"
	"os"

	"github.com/spf13/afero"
)

type StructParser struct {
	filePath  string
	structName string
}

func NewStructParser(filePath string, structName string) *StructParser {
	return &StructParser{
		filePath: filePath,
		structName: structName,
	}
}

func (p *StructParser) Parse() (*ast.StructType, error) {
	f, err := os.ReadFile(p.filePath)
	if err != nil {
		return nil, err
	}

	// Create a temporary directory to store generated files
	tempDir, err := ioutil.TempDir("", "avro-")
	if err != nil {
		return nil, err
	}
	defer func() { _ = os.RemoveAll(tempDir) }()

	// Write the raw JSON to a temp file
	err = ioutil.WriteFile(fmt.Sprintf("%s/%s.json", tempDir, p.structName), f, 0644)
	if err != nil {
		return nil, err
	}

	// Load the JSON data
	jsonBytes, err := ioutil.ReadFile(fmt.Sprintf("%s/%s.json", tempDir, p.structName))
	if err != nil {
		return nil, err
	}

	var astNode ast.Node
	if err := json.Unmarshal(jsonBytes, &astNode); err != nil {
		return nil, fmt.Errorf("failed to unmarshal JSON: %w", err)
	}

	// Get the type of the struct node
	structType := astutil.Lookup(&astNode, ast.NewIdent(fmt.Sprintf("%s_struct", p.structName)))

	// Check if the struct has any fields
	if len(structType.Fields.List) == 0 {
		return nil, fmt.Errorf("the struct does not have any fields")
	}

	// Generate the AVRO schema
	schema := avro.GenerateSchemaFromAST(astutil.Scope{AstNode: structType})
	fmt.Println(schema)

	// Format the schema for better readability
	formattedSchema, err := format.Source([]byte(schema))
	if err != nil {
		return nil, err
	}

	// Save the formatted schema to the target file
	targetFilePath := fmt.Sprintf("%s/%s.avsc", tempDir, p.structName)
	err = ioutil.WriteFile(targetFilePath, formattedSchema, 0644)
	if err != nil {
		return nil, err
	}

	// Return the formatted schema
	return &schema, nil
}

func main() {
	args := os.Args[1:]
	if len(args) < 2 {
		log.Fatalf("Usage: %v <source_file> <struct_name>", os.Args[0])
	}

	parser := NewStructParser(args[0], args[1])

	if parser.Parse() == nil {
		log.Printf("Generated schema saved at %s/%s.avsc", parser.filePath, parser.structName)
	} else {
		log.Fatal(parser.Parse())
	}
}
```

### How to Use This Program:

1. **Compile the Program**:
   ```sh
   go build -o avro_parser avro_parser.go
   ```

2. **Run the Program**:
   ```sh
   ./avro_parser your_go_source_file.go my_struct_name
   ```

   For example:
   ```sh
   ./avro_parser my_source.go MyStruct
   ``

